<section class="panel"><div class="panel-head"><div><small>FILTROS</small><h3>Documentos fiscais</h3></div></div><form method="get" class="settings-form"><div class="settings-grid"><label class="settings-field">Buscar<input name="q" value="<?=e($searchFilter)?>" placeholder="pedido, loja, chave ou número"></label><label class="settings-field">Status<select name="status"><option value="">Todos</option><?php foreach(['pending','configuration_required','validation_failed','ready','submitting','processing','authorized','rejected','error','awaiting_manual','awaiting_external','cancelled','voided'] as $value):?><option value="<?=e($value)?>" <?=$statusFilter===$value?'selected':''?>><?=e(str_replace('_',' ',$value))?></option><?php endforeach;?></select></label><label class="settings-field">Modo<select name="mode"><option value="">Todos</option><?php foreach(['platform'=>'Tuffer/provider','manual'=>'Manual','external'=>'ERP/API'] as $value=>$label):?><option value="<?=e($value)?>" <?=$modeFilter===$value?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label class="settings-field">Pendência<select name="action"><option value="0">Todos</option><option value="1" <?=$actionFilter?'selected':''?>>Somente requer ação</option></select></label></div><button class="button button--secondary">Filtrar</button></form></section>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>ID</th><th>Pedido</th><th>Loja</th><th>Modo</th><th>Status</th><th>NF-e</th><th>Pendência</th></tr></thead><tbody><?php if(!$documents):?><tr><td colspan="7">Nenhum documento encontrado.</td></tr><?php endif;?><?php foreach($documents as $d):?><tr><td><a href="<?=e(url('/admin/fiscal/'.(int)$d['id']))?>">#<?=(int)$d['id']?></a></td><td><strong><?=e($d['seller_order_code'])?></strong><small><?=e($d['order_code'])?></small></td><td><strong><?=e($d['store_name'])?></strong><small><?=e($d['seller_name'])?></small></td><td><?=e((string)$d['issuance_mode'])?><small><?=e((string)$d['provider'])?></small></td><td><?=e(str_replace('_',' ',(string)$d['status']))?></td><td><?php if($d['access_key']):?>Nº <?=e((string)$d['number'])?> · série <?=e((string)$d['series'])?><small style="word-break:break-all"><?=e((string)$d['access_key'])?></small><?php else:?>—<?php endif;?></td><td><?=!empty($d['requires_action'])?e((string)($d['action_reason']??'Revisão necessária')):'—'?></td></tr><?php endforeach;?></tbody></table></div></section>
